/* Messages in the bell (round BC): user_notifications (part 85) takes one more kind, 'direct_message', so a message between members is one row in the recipient's bell per conversation, rewritten in place as more messages arrive and read when the conversation is opened (lib/notifications/dm-notify-shared.ts). Every kind it took before is kept. Before this has run the table's check refuses the kind and messages are told the way they were, by the push alone; nothing breaks. Needs part 85 (it says so and changes nothing without it). Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.user_notifications') IS NULL THEN RAISE NOTICE 'part 283: there is no user_notifications here, run part 85 first.'; RETURN; END IF; ALTER TABLE public.user_notifications DROP CONSTRAINT IF EXISTS user_notifications_kind_check, ADD CONSTRAINT user_notifications_kind_check CHECK (kind IN ('new_follower', 'followed_new_product', 'followed_new_community', 'membership_post', 'purchased_creator_new_product', 'system', 'direct_message')); END $do$;
notify pgrst, 'reload schema';
